import { Popover, Button } from "march/ui"

// not için ruh hali: düğmeye basınca emoji paneli açılır, seçince kapanır
const moods = ["😀", "😌", "😴", "🤩", "😤", "🥳"]

export function EmojiNote() {
  let $mood = "😀"
  return <Popover trigger={<Button variant="secondary">Ruh hali: {$mood}</Button>} title="Bugün nasılsın?" placement="bottom-start">
    {(close: () => void) => <div sx={{ flex: "row", gap: 1 }}>
      {moods.map((m) => <Button variant="ghost" on:click={() => { $mood = m; close() }}>{m}</Button>)}
    </div>}
  </Popover>
}

import { Popover, Button, TextInput, toast } from "march/ui"
import { link } from "march/icons"

// paylaşım bağlantısı: açılır panelde bağlantı ve kopyala; alt çubukta kapat
export function ShareLink() {
  const url = "https://marchjs.com/p/42"
  return <Popover trigger={<Button icon={link}>Paylaş</Button>} title="Bağlantıyı paylaş" width="md" closable
    footer={<span sx={{ text: "xs", color: "muted" }}>Bağlantısı olan herkes görebilir</span>}>
    {(close: () => void) => <div sx={{ flex: "row", gap: 2 }}>
      <TextInput aria-label="Bağlantı" value={url} readOnly />
      <Button variant="primary" on:click={() => { toast("Kopyalandı"); close() }}>Kopyala</Button>
    </div>}
  </Popover>
}

import { Popover, Button } from "march/ui"

// Popover'ın özellikleri: trigger, open / setOpen (denetimli), defaultOpen, onOpenChange, placement, title, closable,
// closeLabel, label, role, motion, width, flush, footer, closeOnOutside, closeOnEscape, autoFocus, color, class,
// panelClass ve işlev çocuk (close)
export function PopoverLab() {
  let $open = false
  let $why = "—"
  return <div sx={{ flex: "col", gap: 2 }}>
    <Popover class="lab-pop" panelClass="lab-panel" trigger={<Button>Ayrıntı</Button>} open={$open} setOpen={(v: boolean) => $open = v}
      onOpenChange={(o: boolean, why: string) => $why = `${o ? "açıldı" : "kapandı"} (${why})`} placement="bottom" title="Ayrıntı" closable
      closeLabel="Paneli kapat" label="Ayrıntı paneli" motion="fade" width="sm" footer={<span>Alt bilgi</span>} closeOnOutside={false}
      closeOnEscape autoFocus={false} color="brand-purple">
      {(close: () => void) => <Button size="sm" on:click={() => close()}>Tamam</Button>}
    </Popover>
    <span class="lab-why">{$why}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PopoverLab } from "./PopoverLab.tsx"

// PopoverLab'in testleri: kaydedince Testler sekmesinde çalışır
test("tetikleyiciye basınca panel açılır ve nedeni yazılır", async () => {
  const s = renderTest(() => <PopoverLab />)
  await s.click("Ayrıntı")
  await s.flush(2)
  expect(s.get(".lab-why")?.textContent).toContain("açıldı")
  expect(s.sees("Alt bilgi")).toBe(true)
})

test("işlev çocuğun close'u paneli kapatır", async () => {
  const s = renderTest(() => <PopoverLab />)
  await s.click("Ayrıntı")
  await s.flush(2)
  await s.click("Tamam")
  await s.flush(2)
  expect(s.get(".lab-why")?.textContent).toContain("kapandı")
})
